// ObjectPool.js - Implementa el patrón Object Pool para optimizar la gestión de memoria.
// Reduce la recolección de basura reutilizando instancias de enemigos, proyectiles y partículas.
// Maximiza el rendimiento y la estabilidad de cuadros por segundo en JavaScript.

export class ObjectPool {
  constructor(factory, initialSize = 10, maxSize = 100) {
    this.factory = factory;
    this.pool = [];
    this.active = new Set();
    this.initialSize = initialSize;
    this.maxSize = maxSize;

    for (let i = 0; i < initialSize; i++) {
      this.pool.push(factory());
    }
  }

  acquire() {
    let obj;
    if (this.pool.length > 0) {
      obj = this.pool.pop();
    } else if (this.active.size < this.maxSize) {
      obj = this.factory();
    } else {
      const oldest = this.active.values().next().value;
      if (oldest) {
        this.active.delete(oldest);
        this.pool.push(oldest);
      }
      obj = this.factory();
    }
    
    this.active.add(obj);
    return obj;
  }

  release(obj) {
    if (this.active.has(obj)) {
      this.active.delete(obj);
      this.pool.push(obj);
    }
  }

  releaseAll() {
    for (const obj of this.active) {
      this.pool.push(obj);
    }
    this.active.clear();
  }

  remove(obj) {
    if (this.active.has(obj)) {
      this.active.delete(obj);
      this.pool.push(obj);
    }
  }

  getStats() {
    return {
      available: this.pool.length,
      active: this.active.size,
      total: this.pool.length + this.active.size,
      maxSize: this.maxSize
    };
  }

  clear() {
    this.pool = [];
    this.active.clear();
    for (let i = 0; i < this.initialSize; i++) {
      this.pool.push(this.factory());
    }
  }
}

// Implementa el pool especializado para entidades enemigas.
export class EnemyPool extends ObjectPool {
  constructor(enemyDefs, initialSize = 20, maxSize = 150) {
    // Inicializa el grupo base con la función fábrica de enemigos.
    super(() => EnemyPool.createEnemyTemplate(), initialSize, maxSize);
    this.enemyDefs = enemyDefs;
  }

  static createEnemyTemplate() {
    return {
      type: null,
      x: 0, y: 0, baseY: 0,
      w: 0, h: 0,
      hp: 0, maxHp: 0,
      vx: 0, vy: 0,
      t: 0,
      pattern: null,
      sprite: null,
      color: 0,
      score: 0,
      amp: 0, freq: 0,
      isCarrier: false,
      // Inicializa los parámetros de trayectoria para formaciones en cadena.
      wormRole: 0,
      wormLeader: null,
      wormPhase: 'enter',
      wormFlip: false,
      FOLLOW_DELAY: 30,
      HISTORY_MAX: 600,
      pathHistory: null,
      // Marca el estado activo de la entidad dentro del sistema.
      active: false
    };
  }

  // Extrae y configura una entidad enemiga para su aparición en pantalla.
  acquire(typeKey, y, opts = {}) {
    const enemy = super.acquire();
    const def = this.enemyDefs[typeKey];
    
    // Restablece los atributos principales de posición, vida y estado.
    enemy.type = typeKey;
    enemy.x = 680 + (opts.delay || 0) * 155;
    enemy.y = y;
    enemy.baseY = y;
    enemy.w = def.w;
    enemy.h = def.h;
    enemy.hp = def.hp;
    enemy.maxHp = def.hp;
    enemy.vx = def.vx + (Math.random() * 16 - 8);
    enemy.vy = def.vy || 0;
    enemy.t = opts.phase || Math.random() * 0.5;
    enemy.pattern = def.pattern;
    enemy.sprite = def.sprite;
    enemy.color = def.color;
    enemy.score = def.score;
    enemy.amp = def.amp || 0;
    enemy.freq = def.freq || 0;
    enemy.isCarrier = !!def.isCarrier;
    enemy.active = true;
    
    // Restablece los temporizadores y banderas de comportamiento.
    enemy.wormRole = 0;
    enemy.wormLeader = null;
    enemy.wormPhase = 'enter';
    enemy.wormFlip = false;
    enemy.pathHistory = null;
    
    if (enemy.pattern === 'zigzag') {
      enemy.vy = def.vy * (Math.random() > 0.5 ? 1 : -1);
    }
    
    return enemy;
  }

  // Configura los atributos requeridos para el comportamiento en formación ondulante.
  acquireInterceptorWorm(typeKey, startX, startY, wormRole, wormLeader, pathHistory) {
    const enemy = super.acquire();
    const def = this.enemyDefs[typeKey];
    
    enemy.type = typeKey;
    enemy.x = startX;
    enemy.y = startY;
    enemy.baseY = startY;
    enemy.w = def.w;
    enemy.h = def.h;
    enemy.hp = def.hp;
    enemy.maxHp = def.hp;
    enemy.vx = 128;
    enemy.vy = 0;
    enemy.t = 0;
    enemy.pattern = 'interceptor_worm';
    enemy.sprite = def.sprite;
    enemy.color = def.color;
    enemy.score = def.score;
    enemy.amp = 0;
    enemy.freq = 0;
    enemy.isCarrier = false;
    enemy.active = true;
    
    // Aplica los parámetros de movimiento ondulatorio.
    enemy.wormRole = wormRole;
    enemy.wormLeader = wormLeader;
    enemy.wormPhase = 'enter';
    enemy.wormFlip = false;
    enemy.FOLLOW_DELAY = 30;
    enemy.HISTORY_MAX = 600;
    enemy.pathHistory = pathHistory;
    
    return enemy;
  }
}

// Implementa el pool especializado para proyectiles del jugador y enemigos.
export class ProjectilePool extends ObjectPool {
  constructor(initialSize = 50, maxSize = 200) {
    super(() => ProjectilePool.createProjectileTemplate(), initialSize, maxSize);
  }

  static createProjectileTemplate() {
    return {
      x: 0, y: 0,
      vx: 0, vy: 0,
      w: 0, h: 0,
      life: 0,
      isLaser: false,
      isMissile: false,
      fromOption: false,
      color: 18, // Color por defecto (blanco)
      active: false
    };
  }

  // Extrae y configura un proyectil según su origen y trayectoria.
  acquire(x, y, vx, vy, opts = {}) {
    const projectile = super.acquire();
    
    projectile.x = x;
    projectile.y = y;
    projectile.vx = vx;
    projectile.vy = vy;
    projectile.w = opts.w || 6;
    projectile.h = opts.h || 3;
    projectile.life = opts.life || 4.5;
    projectile.isLaser = !!opts.isLaser;
    projectile.isMissile = !!opts.isMissile;
    projectile.fromOption = !!opts.fromOption;
    projectile.color = opts.color || 18; // Color específico del proyectil
    projectile.active = true;
    
    return projectile;
  }
}

// Implementa el pool especializado para partículas y efectos de explosión.
export class ParticlePool extends ObjectPool {
  constructor(initialSize = 30, maxSize = 100) {
    super(() => ParticlePool.createParticleTemplate(), initialSize, maxSize);
  }

  static createParticleTemplate() {
    return {
      x: 0, y: 0,
      vx: 0, vy: 0,
      life: 0,
      maxLife: 0.6,
      c: 0,
      active: false
    };
  }

  acquire(x, y, vx, vy, life, maxLife, color) {
    const particle = super.acquire();
    
    particle.x = x;
    particle.y = y;
    particle.vx = vx;
    particle.vy = vy;
    particle.life = life;
    particle.maxLife = maxLife;
    particle.c = color;
    particle.active = true;
    
    return particle;
  }
}
