export function clampPalette(palette, max = 45) {
  if (!Array.isArray(palette)) {return Palettes.VECTOR;}
  return palette.slice(0, max);
}

export function isValidHexColor(str) {
  return /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(str);
}
